WITH MajorsWithMembers AS (
  SELECT DISTINCT link_to_major FROM member WHERE link_to_major IS NOT NULL
),
MajorCounts AS (
  SELECT 
    (SELECT COUNT(*) FROM major) AS total_majors,
    (SELECT COUNT(*) FROM major WHERE major_id NOT IN (SELECT link_to_major FROM MajorsWithMembers)) AS majors_without_members
)
SELECT ROUND(majors_without_members * 100.0 / total_majors, 2) AS percentage_majors_without_members
FROM MajorCounts;

WITH marvel AS (
  SELECT id FROM publisher WHERE publisher_name = 'Marvel Comics'
), dc AS (
  SELECT id FROM publisher WHERE publisher_name = 'DC Comics'
), marvel_heroes AS (
  SELECT id, height_cm FROM superhero WHERE publisher_id IN (SELECT id FROM marvel) AND height_cm IS NOT NULL
), dc_heroes AS (
  SELECT id FROM superhero WHERE publisher_id IN (SELECT id FROM dc)
), 
marvel_powers AS (
  SELECT DISTINCT hp.hero_id, hp.power_id FROM hero_power hp 
  JOIN marvel_heroes mh ON mh.id = hp.hero_id
), dc_powers AS (
  SELECT DISTINCT hp.power_id FROM hero_power hp 
  JOIN dc_heroes dh ON dh.id = hp.hero_id
), 
unique_marvel_powers AS (
  SELECT DISTINCT power_id FROM marvel_powers
  WHERE power_id NOT IN (SELECT power_id FROM dc_powers)
), 
marvel_heroes_unique_power AS (
  SELECT DISTINCT hero_id FROM marvel_powers
  WHERE power_id IN (SELECT power_id FROM unique_marvel_powers)
)

SELECT AVG(height_cm) AS average_height_cm
FROM marvel_heroes
WHERE id IN (SELECT hero_id FROM marvel_heroes_unique_power);

WITH abomb_race AS (
  SELECT race_id FROM superhero WHERE superhero_name = 'A-Bomb'
), abomb_group_heights AS (
  SELECT height_cm FROM superhero
  WHERE race_id = (SELECT race_id FROM abomb_race)
    AND height_cm IS NOT NULL
)
SELECT ROUND(AVG(height_cm), 1) AS avg_height_cm FROM abomb_group_heights;

